<script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.11.0/html2pdf.bundle.min.js"></script>
<script>
    function printInvoice(invoiceContainer) {
        if (!invoiceContainer) return;

        var bodyContent = invoiceContainer.querySelector('.page');
        if (!bodyContent) return;

        // Clone the page
        var printContents = bodyContent.cloneNode(true);

        // Wait for images to load
        const images = printContents.querySelectorAll('img');

        Promise.all(
            Array.from(images).map(img => {
                return new Promise(resolve => {
                    if (img.complete && img.naturalWidth !== 0) {
                        resolve();
                    } else {
                        img.onload = resolve;
                        img.onerror = resolve;
                    }
                });
            })
        ).then(() => {

            var printWindow = window.open('', '_blank');

            printWindow.document.open();

            printWindow.document.write(`
                <!DOCTYPE html>
                <html>
                <head>
                    <title>Invoice</title>
            `);

            // Copy ALL existing styles
            document.querySelectorAll('style, link[rel="stylesheet"]').forEach(function(el){
                printWindow.document.write(el.outerHTML);
            });

            printWindow.document.write(`
                <style>
                    html,body{
                        margin:0;
                        padding:0;
                        background:#fff;
                    }

                    body{
                        display:flex;
                        justify-content:center;
                        align-items:flex-start;
                    }

                    .page{
                        margin:0 !important;
                        box-shadow:none !important;
                        page-break-after:avoid;
                        break-after:avoid;
                    }

                    @page{
                        margin:0;
                        size:A4 portrait;
                    }
                </style>
                </head>
                <body>
            `);

            printWindow.document.body.appendChild(printContents);

            printWindow.document.write(`
                </body>
                </html>
            `);

            printWindow.document.close();

            printWindow.onload = function () {

                setTimeout(function () {

                    printWindow.focus();

                    printWindow.print();

                    printWindow.close();

                }, 500);

            };

        });
    }
    function downloadInvoice(invoiceContainer) {
    if (!invoiceContainer) return;

    var bodyContent = invoiceContainer.querySelector('.page');
    if (!bodyContent) return;

    var clone = bodyContent.cloneNode(true);
    clone.style.boxShadow = "none";
    clone.style.margin = "0";

    var invoiceNumber = bodyContent.querySelector('.fw-bold.text-primary');
    var filename = (invoiceNumber
        ? invoiceNumber.textContent.trim()
        : 'invoice') + '.pdf';

    // Convert SVG data URIs to PNG data URIs with higher resolution
    const svgImages = clone.querySelectorAll('img[src*="data:image/svg"]');
    
    let svgPromises = Array.from(svgImages).map(img => {
        return new Promise((resolve) => {
            try {
                const svgDataUri = img.src;
                
                // Create canvas with higher DPI scaling
                const dpiScale = 1; // Increase scale from 2 to 3 for better quality
                const canvas = document.createElement('canvas');
                canvas.width = (img.width || 909) * dpiScale;
                canvas.height = (img.height || 1286) * dpiScale;
                const ctx = canvas.getContext('2d');
                
                // Enable image smoothing for better quality
                ctx.imageSmoothingEnabled = true;
                ctx.imageSmoothingQuality = 'high';
                
                // Create image from SVG
                const image = new Image();
                image.crossOrigin = "anonymous";
                
                image.onload = function() {
                    // Draw image to canvas with scaling
                    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
                    
                    // Convert canvas to PNG data URI with higher quality
                    const pngDataUri = canvas.toDataURL('image/png');
                    img.src = pngDataUri;
                    img.style.width = '100%';
                    img.style.height = '100%';
                    img.style.display = 'block';
                    img.style.imageRendering = 'crisp-edges'; // Prevent browser scaling blur
                    
                    resolve();
                };
                
                image.onerror = function() {
                    console.warn("SVG failed to load, skipping conversion");
                    resolve();
                };
                
                // Load SVG
                image.src = svgDataUri;
                
            } catch (error) {
                console.error("SVG conversion error:", error);
                resolve();
            }
        });
    });

    Promise.all(svgPromises).then(() => {
        setTimeout(() => {
            html2pdf().set({
                margin: 0,
                filename: filename,
                image: {
                    type: 'png',
                    quality: 1.0
                },
                html2canvas: {
                    scale: 1, // Increased from 2 to 3 for higher resolution
                    useCORS: true,
                    allowTaint: true,
                    backgroundColor: "#ffffff",
                    scrollX: 0,
                    scrollY: 0,
                    logging: false,
                    letterRendering: true,
                    imageTimeout: 15000,
                    onclone: function(clonedDocument) {
                        const clonedImages = clonedDocument.querySelectorAll('img');
                        clonedImages.forEach(img => {
                            img.style.display = "block";
                            img.style.visibility = "visible";
                            img.style.imageRendering = 'crisp-edges';
                        });
                    }
                },
                jsPDF: {
                    unit: 'px',
                    format: [909, 1286],
                    orientation: 'portrait',
                    compress: false // Disable compression to maintain quality
                }
            })
            .from(clone)
            .save()
            .catch(err => {
                console.error("PDF error:", err);
                alert("Error generating PDF. Please try again.");
            });
        }, 500);
    }).catch(err => {
        console.error("Promise error:", err);
        alert("Error processing images for PDF.");
    });
}
</script>
